// seed: tests/seed.company.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/company.json') });

const ACTIONS = ['צפייה בפרטי המכרז', 'עריכת מכרז', 'קידום המכרז', 'הארכת המכרז', 'סגירת מכרז', 'העברה לארכיון'];

test.describe('Tender owner actions (company)', () => {
  test('Owner sees «פעולות מכרז» on the card and on the tender page @desktop @prod-safe #cf6dc1', async ({ page }) => {
    // 1. «המכרזים שלי»
    await page.goto('/tenders?mine=1');
    const cards = page.getByRole('listitem').filter({ has: page.getByRole('link', { name: /^לפרטי המכרז/ }) });
    // skip tenders created by the parallel @data tests (they change title/status during the run)
    const card = cards
      .filter({ has: page.getByText('פעיל', { exact: true }) })
      .filter({ hasNot: page.getByRole('heading', { level: 3, name: /^QA-AUTO-(cf6dc1|bc890b)-\d+/ }) })
      .first();
    await expect(card).toBeVisible();
    const title = (await card.getByRole('heading', { level: 3 }).innerText()).trim();

    // 2. «•••» on the first active card — Expected: exactly the six actions
    await card.getByRole('button', { name: 'פעולות מכרז' }).click();
    await expect(page.getByRole('menuitem')).toHaveText(ACTIONS);

    // 3. Escape → open the tender → «•••» next to the tender number — Expected: the same actions without «צפייה בפרטי המכרז»
    //    (the page itself is the view; matches the accepted QA evidence cf6dc1-T1-page-menu-desktop.png, 21.10.2026)
    await page.keyboard.press('Escape');
    await expect(page.getByRole('menu')).toHaveCount(0);
    await card.getByRole('link', { name: /^לפרטי המכרז/ }).click();
    const details = page.getByRole('dialog', { name: 'פרטי המכרז' });
    await expect(details.getByRole('heading', { level: 3, name: title, exact: true })).toBeVisible();
    await details.getByRole('button', { name: 'פעולות מכרז' }).click();
    await expect(page.getByRole('menuitem')).toHaveText(ACTIONS.slice(1));

    // 4. Escape, close the dialog — Expected: the tender is still «פעיל»
    await page.keyboard.press('Escape');
    await expect(page.getByRole('menu')).toHaveCount(0);
    // (Escape inside the dialog may also close the dialog itself)
    if (await details.isVisible()) await details.getByRole('button', { name: 'סגירה' }).click();
    await expect(details).toBeHidden();
    const sameCard = cards.filter({ has: page.getByRole('heading', { level: 3, name: title, exact: true }) }).first();
    await expect(sameCard.getByText('פעיל', { exact: true })).toBeVisible();
  });
});
